/// Spaziature in pixel di design (--ms-s-N).
abstract final class MsSpace {
  static const double s0 = 0;
  static const double s1 = 4;
  static const double s2 = 8;
  static const double s3 = 12;
  static const double s4 = 16;
  static const double s5 = 20;
  static const double s6 = 24;
  static const double s8 = 32;
  static const double s10 = 40;
  static const double s12 = 48;
  static const double s16 = 64;
  static const double s20 = 80;
}

/// Misure fisse in pixel di design.
abstract final class MsSize {
  static const double px = 2;
  static const double px2 = 4;
  static const double target = 44;
  static const double control = 44;
  static const double controlLg = 56;
  static const double play = 72;
  static const double maxWidth = 1760;
}

/// Livelli di sovrapposizione.
abstract final class MsZ {
  static const double base = 0;
  static const double raised = 10;
  static const double sticky = 100;
  static const double dropdown = 200;
  static const double scrim = 300;
  static const double dialog = 400;
  static const double toast = 500;
  static const double tooltip = 600;
}

/// Durate delle animazioni (--ms-dur-N).
abstract final class MsDuration {
  static const Duration d0 = Duration(milliseconds: 0);
  static const Duration d1 = Duration(milliseconds: 80);
  static const Duration d2 = Duration(milliseconds: 160);
  static const Duration d3 = Duration(milliseconds: 240);
  static const Duration d4 = Duration(milliseconds: 400);
}

/// Scala tipografica: dimensione e interlinea in pixel di design.
abstract final class MsTypeScale {
  static const (double, double) display = (40, 48);
  static const (double, double) h1 = (32, 40);
  static const (double, double) h2 = (24, 32);
  static const (double, double) h3 = (20, 28);
  static const (double, double) lg = (18, 28);
  static const (double, double) md = (16, 24);
  static const (double, double) sm = (14, 20);
  static const (double, double) label = (15, 24);
  static const (double, double) con = (14, 20);
}
